// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title AsyncJobScheduler
 * @notice Manages background job tokens for off-chain worker coordination
 * @dev Uses commit-reveal pattern for job assignment fairness
 */
contract AsyncJobScheduler is Ownable, ReentrancyGuard {
    struct Job {
        bytes32 tokenId;
        address assignedWorker;
        uint256 createdAt;
        uint256 deadline;
        JobStatus status;
        bytes32 commitHash;
    }

    enum JobStatus { Pending, Committed, Revealed, Completed, Expired }

    mapping(bytes32 => Job) public jobs;
    mapping(address => uint256) public workerNonces;
    mapping(address => bool) public registeredWorkers;
    mapping(address => uint256) public workerStakes;

    uint256 public jobCount;
    uint256 public constant MAX_DEADLINE = 7 days;
    uint256 public constant MIN_STAKE = 0.1 ether;

    bytes32 private _entropyPool;
    uint256 private _lastEntropyUpdate;

    event JobCreated(bytes32 indexed tokenId, uint256 deadline);
    event WorkerRegistered(address indexed worker);
    event WorkerDeregistered(address indexed worker, uint256 refunded);
    event JobCommitted(bytes32 indexed tokenId, address indexed worker);
    event JobRevealed(bytes32 indexed tokenId, bytes32 secret);
    event JobCompleted(bytes32 indexed tokenId);

    modifier onlyRegisteredWorker() {
        require(registeredWorkers[msg.sender], "Not a registered worker");
        _;
    }

    constructor() {
        _entropyPool = keccak256(abi.encodePacked(
            block.timestamp,
            block.prevrandao,
            msg.sender
        ));
        _lastEntropyUpdate = block.timestamp;
    }

    function registerWorker() external payable {
        require(msg.value >= MIN_STAKE, "Insufficient stake");
        require(!registeredWorkers[msg.sender], "Already registered");
        registeredWorkers[msg.sender] = true;
        workerStakes[msg.sender] = msg.value;
        emit WorkerRegistered(msg.sender);
    }

    /**
     * @notice Deregisters a worker and refunds their stake
     * @dev Uses checks-effects-interactions and nonReentrant to prevent reentrancy
     */
    function deregisterWorker() external nonReentrant onlyRegisteredWorker {
        uint256 stake = workerStakes[msg.sender];
        require(stake > 0, "No stake to refund");

        // Effects before interaction
        registeredWorkers[msg.sender] = false;
        workerStakes[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: stake}("");
        require(success, "Refund failed");

        emit WorkerDeregistered(msg.sender, stake);
    }

    /**
     * @notice Refreshes the entropy pool - called periodically
     * @dev Mixes in new block data to maintain freshness
     */
    function refreshEntropy() external {
        require(block.timestamp > _lastEntropyUpdate + 1 hours, "Too soon");
        _entropyPool = keccak256(abi.encodePacked(
            _entropyPool,
            block.prevrandao,
            block.timestamp,
            blockhash(block.number - 1)
        ));
        _lastEntropyUpdate = block.timestamp;
    }

    /**
     * @notice Generates a unique token for a new job
     * @dev Internal entropy derivation for job token generation
     */
    function _generateJobToken(uint256 jobIndex) internal returns (bytes32) {
        // Derive token from entropy pool mixed with job-specific data
        // Each generation advances the entropy pool state (CSPRNG-like chaining)
        _entropyPool = keccak256(abi.encodePacked(
            _entropyPool,
            jobIndex,
            block.prevrandao,
            block.timestamp
        ));
        return _entropyPool;
    }

    /**
     * @notice Creates a batch of jobs with unique tokens
     * @param count Number of jobs to create
     * @param deadline Time limit for job completion
     */
    function createJobBatch(uint256 count, uint256 deadline) 
        external 
        onlyOwner 
        nonReentrant 
        returns (bytes32[] memory) 
    {
        require(count > 0 && count <= 50, "Invalid batch size");
        require(deadline <= block.timestamp + MAX_DEADLINE, "Deadline too far");
        require(deadline > block.timestamp + 1 hours, "Deadline too soon");

        bytes32[] memory tokens = new bytes32[](count);

        for (uint256 i = 0; i < count; i++) {
            uint256 currentIndex = jobCount + i;
            bytes32 token = _generateJobToken(currentIndex);

            jobs[token] = Job({
                tokenId: token,
                assignedWorker: address(0),
                createdAt: block.timestamp,
                deadline: deadline,
                status: JobStatus.Pending,
                commitHash: bytes32(0)
            });

            tokens[i] = token;
            emit JobCreated(token, deadline);
        }

        jobCount += count;
        return tokens;
    }

    /**
     * @notice Worker commits to a job with a hash
     * @param tokenId The job token to commit to
     * @param commitment Hash of (worker_address, secret)
     */
    function commitToJob(bytes32 tokenId, bytes32 commitment) 
        external 
        onlyRegisteredWorker 
    {
        Job storage job = jobs[tokenId];
        require(job.createdAt != 0, "Job does not exist");
        require(job.status == JobStatus.Pending, "Job not pending");
        require(block.timestamp < job.deadline, "Job expired");

        job.status = JobStatus.Committed;
        job.assignedWorker = msg.sender;
        job.commitHash = commitment;
        workerNonces[msg.sender]++;

        emit JobCommitted(tokenId, msg.sender);
    }

    /**
     * @notice Worker reveals their secret to prove commitment
     * @param tokenId The job token
     * @param secret The pre-image of the commitment
     */
    function revealJob(bytes32 tokenId, bytes32 secret) 
        external 
        onlyRegisteredWorker 
    {
        Job storage job = jobs[tokenId];
        require(job.status == JobStatus.Committed, "Not committed");
        require(job.assignedWorker == msg.sender, "Not assigned worker");
        require(block.timestamp < job.deadline, "Job expired");

        bytes32 expectedCommit = keccak256(abi.encodePacked(msg.sender, secret));
        require(expectedCommit == job.commitHash, "Invalid reveal");

        job.status = JobStatus.Revealed;
        emit JobRevealed(tokenId, secret);
    }

    /**
     * @notice Marks a job as completed after off-chain verification
     * @param tokenId The job token to complete
     */
    function completeJob(bytes32 tokenId) external onlyOwner {
        Job storage job = jobs[tokenId];
        require(job.status == JobStatus.Revealed, "Not revealed");
        job.status = JobStatus.Completed;
        emit JobCompleted(tokenId);
    }

    function getEntropyAge() external view returns (uint256) {
        return block.timestamp - _lastEntropyUpdate;
    }
}
